361	        List<BigDecimal> amounts = inclusiveAmounts();
362	        List<BigDecimal> exact = clientPricesIncludeTax ? null : exactLineTaxes(taxRate);
363	        for (Map.Entry<BigDecimal, List<Integer>> group : byRate(taxRate, !clientPricesIncludeTax).entrySet()) {
364	            List<Integer> indexes = group.getValue();
365	            BigDecimal amount = zero();
366	            for (int i : indexes) {
367	                amount = amount.add(amounts.get(i));
368	            }
369	            if (indexes.size() == 1 && indexes.get(0) == lines.size() && amount.signum() == 0) {
370	                continue;
371	            }
372	            BigDecimal rate = group.getKey();
373	            BigDecimal tax = clientPricesIncludeTax
374	                    ? (rate.signum() == 0 ? zero() : inclusiveRateTax(amounts, rate, indexes))
375	                    : roundTax(indexes.stream().map(exact::get).toList());
376	            result.put(rate, new BigDecimal[] { clientPricesIncludeTax ? amount.subtract(tax) : amount, tax });
377	        }
378	        return result;
379	    }
