382	     * Each line's tax taken out of tax-inclusive prices, in the order of the lines; none when the prices
383	     * do not include tax. A reverse-charged invoice has it taken out as usual, though it is not charged.
384	     */
385	    public List<BigDecimal> lineTaxesInside(BigDecimal taxRate) {
386	        return clientPricesIncludeTax ? inclusiveLineTaxes(taxRate) : lines.stream().map(l -> zero()).toList();
387	    }
