398	    private List<BigDecimal> inclusiveAmounts() {
399	        List<BigDecimal> shares = discountShares();
400	        List<BigDecimal> amounts = new ArrayList<>(lines.size() + 1);
401	        for (int i = 0; i < lines.size(); i++) {
402	            amounts.add(lines.get(i).amount(scale()).subtract(shares.get(i)));
403	        }
404	        amounts.add(surcharge().add(chargedMinimum()));
