408	    /** The tax inside a tax-inclusive amount at the given rate: the amount less it divided by 1 plus the rate, rounded half up. */
409	    private BigDecimal taxInside(BigDecimal amount, BigDecimal rate) {
410	        return amount.subtract(amount.divide(BigDecimal.ONE.add(rate.movePointLeft(2)), scale(), RoundingMode.HALF_UP));
411	    }
