414	     * The tax inside the total of one rate's tax-inclusive amounts (by index); in a region that requires
415	     * it, the exact tax inside rounded down to the cent instead.
416	     */
417	    private BigDecimal inclusiveRateTax(List<BigDecimal> amounts, BigDecimal rate, List<Integer> group) {
418	        BigDecimal taxed = zero();
419	        for (int i : group) {
420	            taxed = taxed.add(amounts.get(i));
421	        }
422	        if (regionRoundsDown) {
423	            return taxed.multiply(rate).divide(BigDecimal.valueOf(100).add(rate), scale(), RoundingMode.DOWN);
424	        }
425	        return taxInside(taxed, rate);
