428	    /**
429	     * The tax inside tax-inclusive prices: for each rate (a line's own, otherwise the client's), the tax
430	     * inside the total of the lines' amounts after their discount shares at that rate (with the
431	     * surcharge and the minimum charge at the client's rate), rounded half up to the cent (down in a
432	     * region that requires it); the invoice
433	     * tax is the total over the rates.
434	     */
435	    private BigDecimal inclusiveTax(BigDecimal taxRate) {
436	        List<BigDecimal> amounts = inclusiveAmounts();
437	        BigDecimal tax = zero();
438	        for (Map.Entry<BigDecimal, List<Integer>> group : byRate(taxRate, false).entrySet()) {
439	            tax = tax.add(inclusiveRateTax(amounts, group.getKey(), group.getValue()));
440	        }
441	        return tax;
442	    }
