444	    /**
445	     * Each line's tax inside tax-inclusive prices, in the order of the lines: the tax inside the line's
446	     * amount after its discount share at the line's rate; exempt lines have none. For each rate, the
447	     * cents by which its lines miss the tax inside their total go (or come off) one at a time to its
448	     * lines with the largest amounts, the earlier line on a tie.
449	     */
450	    private List<BigDecimal> inclusiveLineTaxes(BigDecimal taxRate) {
451	        List<BigDecimal> amounts = inclusiveAmounts();
452	        int n = lines.size();
453	        List<BigDecimal> taxes = new ArrayList<>(n);
454	        for (int i = 0; i < n; i++) {
455	            taxes.add(zero());
456	        }
457	        BigDecimal cent = BigDecimal.ONE.movePointLeft(scale());
458	        for (Map.Entry<BigDecimal, List<Integer>> group : byRate(taxRate, false).entrySet()) {
459	            BigDecimal rate = group.getKey();
460	            if (rate.signum() == 0) {
461	                continue;
462	            }
463	            BigDecimal given = zero();
464	            List<Integer> order = new ArrayList<>();
465	            for (int i : group.getValue()) {
466	                BigDecimal tax = taxInside(amounts.get(i), rate);
467	                // The surcharge and minimum charge keep their own tax, which is not a line's.
468	                if (i < n) {
469	                    taxes.set(i, tax);
470	                    order.add(i);
471	                }
472	                given = given.add(tax);
473	            }
474	            order.sort(Comparator.<Integer, BigDecimal>comparing(amounts::get).reversed().thenComparing(i -> i));
475	            int missing = inclusiveRateTax(amounts, rate, group.getValue()).subtract(given).movePointRight(scale()).intValueExact();
476	            BigDecimal step = missing < 0 ? cent.negate() : cent;
477	            for (int k = 0; k < Math.abs(missing) && !order.isEmpty(); k++) {
478	                int i = order.get(k % order.size());
479	                taxes.set(i, taxes.get(i).add(step));
480	            }
481	        }
482	        return taxes;
483	    }
