525	    /**
526	     * The least the invoice is charged: the client's own minimum charge (in its currency), or else the workspace's,
527	     * converted from US dollars at the pricing date's rate (see {@link #pricingDate}) and rounded down to the step; null
528	     * when no minimum is set.
529	     */
530	    public BigDecimal minimum() {
531	        if (clientMinimumCharge == null && minimumChargeUsd == null) {
532	            return null;
533	        }
534	        return clientMinimumCharge != null ? currency().divideDownToStep(clientMinimumCharge, BigDecimal.ONE)
535	                : currency().divideDownToStep(new BigDecimal(minimumChargeUsd.trim()), usdPerOn(pricingDate()));
