617	    public BigDecimal currentTotal(BigDecimal taxRate) {
618	        BigDecimal amount = discounted().add(surcharge()).add(chargedMinimum()).subtract(getMinimumKeptOff());
619	        if (clientPricesIncludeTax) {
620	            return isReverseCharge() ? currentBeforeTax(taxRate) : amount.subtract(keptTax(taxRate));
