                + " total=" + invoice.total(taxRate.percent()).toPlainString());
    }
    invoice.taxByRate(taxRate.percent()).forEach((rate, amounts) -> audit.record("TAX_CHARGED id="
            + invoice.getId() + " rate=" + rate.stripTrailingZeros().toPlainString() + " net="
