public BigDecimal dunningMinimum(LocalDate today) {
    if (dunningMinimumUsd == null) {
        return zero();
    }
    return currency().divideDownToStep(new BigDecimal(dunningMinimumUsd.trim()), usdPerOn(today));
}

/** A reminder fee charged on the invoice: the fee, in its currency, charged the day the reminder went out. */
public record ReminderFee(LocalDate on, DunningLevel level, BigDecimal amount) {
}

/**
 * The fee for a reminder of the level sent on the day: the workspace's fee for the level in US dollars,
 * converted at the day's rate and rounded down to the step; nothing when the level has none.
 */
public BigDecimal reminderFee(DunningLevel level, LocalDate on) {
    if (reminderFeesUsd == null || reminderFeesUsd.isBlank()) {
        return zero();
    }
    for (String entry : reminderFeesUsd.split(",")) {
        String[] parts = entry.split("=");
        if (parts[0].trim().equals(level.name())) {
            return currency().divideDownToStep(new BigDecimal(parts[1].trim()), usdPerOn(on));
        }
    }
    return zero();
}

/**
 * The reminder fees charged on the invoice, earliest first: each reminder that went out (the n-th at the n-th
 * level after NONE) carries its level's fee from its day (see {@link #reminderFee}); those with no fee, and those
 * after the invoice was written off, charge nothing. A credit note is charged none.
 */
public List<ReminderFee> reminderFees() {
    List<ReminderFee> fees = new ArrayList<>();
    if (isCreditNote()) {
        return fees;
    }
    DunningLevel[] levels = DunningLevel.values();
    for (int n = 0; n < reminders.size() && n + 1 < levels.length; n++) {
        LocalDate on = reminders.get(n);
        if (writtenOffOn != null && on.isAfter(writtenOffOn)) {
            continue;
        }
        BigDecimal fee = reminderFee(levels[n + 1], on);
        if (fee.signum() > 0) {
            fees.add(new ReminderFee(on, levels[n + 1], fee));
        }
    }
    return fees;
}

/** The reminder fees charged on the invoice added up (see {@link #reminderFees}); 0 when none are. */
public BigDecimal getReminderFees() {
    return reminderFees().stream().map(ReminderFee::amount).reduce(zero(), BigDecimal::add);
}

/** Records that the reminder for the next dunning level went out on the given day; it has already been checked. */
public void remind(LocalDate on) {
public BigDecimal getLateInterest() {
    return lateInterest.setScale(scale(), RoundingMode.HALF_UP);
}

/** The late interest written off by waiving it, to the cent; 0 when none was. */
public BigDecimal getLateWaived() {
    return lateWaived.setScale(scale(), RoundingMode.HALF_UP);
}

/** The late interest waived because the last promise to pay was kept, to the cent; 0 when none was. */
public BigDecimal getPromiseWaived() {
    return promiseWaived.setScale(scale(), RoundingMode.HALF_UP);
}

/**
 * The day the last promise to pay was kept by the given day: the day payments (those not reversed) to this invoice
 * and its adjustment notes from the day it was made reached the amount promised, no later than its date; null when
 * it has not been kept.
 */
private LocalDate promiseKeptOn(List<Payment> payments, LocalDate today) {
    if (promiseAmount == null || promiseDate == null || promisedOn == null) {
        return null;
    }
    LocalDate until = promiseDate.isBefore(today) ? promiseDate : today;
    List<Map.Entry<LocalDate, BigDecimal>> paid = payments.stream().filter(p -> !p.isReversed())
            .flatMap(p -> p.getAllocations().stream().filter(a -> countsForPromise(a.getInvoiceId()))
                    .map(a -> Map.entry(a.getDate() == null ? p.getDate() : a.getDate(), a.getAmount())))
            .filter(e -> !e.getKey().isBefore(promisedOn) && !e.getKey().isAfter(until))
            .sorted(Map.Entry.comparingByKey()).toList();
    BigDecimal sum = BigDecimal.ZERO;
    for (Map.Entry<LocalDate, BigDecimal> e : paid) {
        sum = sum.add(e.getValue());
        if (sum.compareTo(promiseAmount) >= 0) {
            return e.getKey();
        }
    }
    return null;
}

/**
 * Works out the late interest charged by the given day, at the annual rate (a percentage), from the
 * payments (those not reversed count), and keeps it as part of what is payable. No late fee is
 * charged. A sent invoice, with something still owed more than {@link #graceDays()} days after its
 * due date, earns interest from the end of its grace period ({@link #graceDays()} days after its due
 * date), compounded daily at rate / 360 (Actual/360): a balance B owing for
 * d days earns B x ((1 + rate / 100 / 360)^d - 1), rounded half up to the cent. Each payment after
 * the grace period ends a period; every period earns interest on what the invoice still owed during it
 * (earlier interest left out), and a payment pays the invoice, then the interest earned
 * so far. A credit note issued after the grace period ends a period too:
 * what it took off what the invoice owed counts only from its issue date, so the periods before it
 * earn interest on what was owed before the credit. None of it is charged until it reaches
 * {@link #interestThreshold()}. On the day the
 * interest was waived (after the day's payments), the interest still unpaid is written off
 * (kept as what was waived) and that day ends a period: interest starts again from it on what is
 * still owed. A written-off invoice is charged only up to the day it was
 * written off. From the day its final notice went out the rate is {@link #FINAL_NOTICE_PREMIUM} points
 * higher (on top of the region's legal maximum), and from the day its collections notice went out it
 * earns no more interest: each of those days ends a period.
 */
public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate, LocalDate asOf) {
    accrueLateInterest(payments, taxRate, annualRate, BigDecimal.ZERO, asOf);
}

/**
 * As {@link #accrueLateInterest(List, BigDecimal, BigDecimal, LocalDate)}, with the premium (percentage
 * points) added on top of the rate once the region's legal maximum has capped it (see {@link #lateInterestRate}).
 */
public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate, BigDecimal premium,
        LocalDate asOf) {
    BigDecimal base = premium == null ? BigDecimal.ZERO : premium;
    InterestRates rates = new InterestRates(lateInterestRate(annualRate, base),
            lateInterestRate(annualRate, base.add(FINAL_NOTICE_PREMIUM)), reminderOn(DunningLevel.FINAL),
            reminderOn(DunningLevel.COLLECTIONS));
    LocalDate today = writtenOffOn != null && writtenOffOn.isBefore(asOf) ? writtenOffOn : asOf;
    this.lateInterest = BigDecimal.ZERO;
    this.lateWaived = BigDecimal.ZERO;
    this.promiseWaived = BigDecimal.ZERO;
    this.milestoneInterest = Map.of();
    if (status == InvoiceStatus.SENT && !isCreditNote() && isBilledByMilestones()) {
        accrueMilestoneInterest(payments, taxRate, rates, today);
        if (getLateInterest().compareTo(interestThreshold()) < 0) {
            this.lateInterest = BigDecimal.ZERO;
            this.milestoneInterest = Map.of();
        }
        return;
    }
    accrueInvoiceInterest(payments, taxRate, rates, today);
    if (getLateInterest().add(getLateWaived()).compareTo(interestThreshold()) < 0) {
        this.lateInterest = BigDecimal.ZERO;
        this.lateWaived = BigDecimal.ZERO;
        this.promiseWaived = BigDecimal.ZERO;
    }
}

/** The percentage points an invoice's late-interest rate rises by from the day its final notice goes out. */
public static final BigDecimal FINAL_NOTICE_PREMIUM = BigDecimal.valueOf(2);

/**
 * The late-interest rates an invoice is charged (annual percentages: the usual rate capped by the region's legal
 * maximum, plus any premiums): the rate until its final notice goes out (finalOn, null when it has not), the raised rate from
 * then, and none from the day its collections notice goes out (stopOn, null when it has not).
 */
private record InterestRates(BigDecimal rate, BigDecimal finalRate, LocalDate finalOn, LocalDate stopOn) {

    /** The daily growth factor of a period starting on the given day (1 once interest has stopped). */
    BigDecimal daily(LocalDate from) {
        if (stopOn != null && !from.isBefore(stopOn)) {
            return BigDecimal.ONE;
        }
        BigDecimal annual = finalOn != null && !from.isBefore(finalOn) ? finalRate : rate;
        return BigDecimal.ONE.add(annual.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128));
    }

    /** The days the rate changes on (the final notice, then collections), earliest first. */
    List<LocalDate> changes() {
        List<LocalDate> days = new ArrayList<>();
        if (finalOn != null) {
            days.add(finalOn);
        }
        if (stopOn != null) {
            days.add(stopOn);
        }
        return days;
    }
}

/** The day this invoice's final notice (its third reminder) went out; null when it has not. */
public LocalDate finalNoticeOn() {
    return reminderOn(DunningLevel.FINAL);
}

/** The day the reminder of the given dunning level went out; null when it has not. */
private LocalDate reminderOn(DunningLevel level) {
    int n = level.reminders() - 1;
    return n >= 0 && n < reminders.size() ? reminders.get(n) : null;
}

/**
 * The late interest an invoice must add up to before any of it is charged: the
 * workspace's threshold in US dollars converted at the issue date's rate, rounded down to the step;
 * 0 when none is set.
 */
private BigDecimal interestThreshold() {
    if (interestThresholdUsd == null) {
        return zero();
    }
    return currency().divideDownToStep(new BigDecimal(interestThresholdUsd.trim()), usdPerOn(issueDate));
}

/**
 * The amount before tax an invoice must reach before anything is withheld: the workspace's threshold
 * in US dollars converted at the issue date's rate, rounded down to the step; 0 when none is set.
 */
private BigDecimal withholdingThreshold() {
    if (withholdingThresholdUsd == null) {
        return zero();
    }
    return currency().divideDownToStep(new BigDecimal(withholdingThresholdUsd.trim()), usdPerOn(issueDate));
}

/** Whether an invoice needs approval before it is sent, has been approved, or needs none. */
public enum Approval {
    NOT_NEEDED, NEEDS_APPROVAL, APPROVED
}

/**
 * The grand total above which a draft needs approval: the approval limit (the client tier's, else the workspace's) in US dollars
 * converted at the issue date's rate, rounded down to the step; null when none is set. A MEDIUM payment risk
 * client's limit is halved in US dollars before it is converted.
 */
private BigDecimal approvalLimit() {
    if (approvalLimitUsd == null) {
        return null;
    }
    BigDecimal usd = new BigDecimal(approvalLimitUsd.trim());
    if (approvalLimitHalved) {
        usd = usd.divide(BigDecimal.valueOf(2));
    }
    return currency().divideDownToStep(usd, usdPerOn(issueDate));
}

/** Halves the approval limit (or restores it): a MEDIUM payment risk client has half the limit. */
public BigDecimal approvalTotal(BigDecimal taxRate) {
    return total(taxRate);
}

/** The number of days an approval stays good after the day it was given: as many as the client's tier allows. */
public int approvalDays() {
    ClientTier tier = ClientTier.orStandard(clientTier);
    return (tier == null ? ClientTier.STANDARD : tier).approvalDays();
}

/**
 * The invoice's approval at the tax rate as of today, judged on its {@link #approvalTotal}: a credit note, or an invoice whose grand total
 * (before any withholding) is not over the approval limit and whose discount takes off no more than a
 * fifth of the subtotal, needs none; otherwise it is approved while its grand total is no more than the total
 * it was approved at and no more than {@link #approvalDays} days have passed since it was approved.
 * Once sent, an invoice is as it was approved. Every draft of a client with a HIGH payment risk (highRisk)
 * needs approval, whatever its size, as does every draft that would take its client over its credit limit
 * (overCreditLimit). A draft whose grand total is more than one and a half times the approval limit, or
 * of a HIGH payment risk client, needs {@link #approvalsRequired two approvals} covering that total. So does
 * a draft that is a possible duplicate of an invoice recently sent to its client (possibleDuplicate). Every
 * draft of a client with an invoice still overdue after its second reminder (remindersIgnored) needs approval.
 */
public Approval approval(BigDecimal taxRate, LocalDate today, boolean highRisk, boolean overCreditLimit,
        boolean possibleDuplicate, boolean remindersIgnored) {
    if (isCreditNote()) {
        return Approval.NOT_NEEDED;
    }
    if (!isDraft()) {
        return approvedTotal == null ? Approval.NOT_NEEDED : Approval.APPROVED;
    }
    BigDecimal limit = approvalLimit();
    BigDecimal total = approvalTotal(taxRate);
    if (!highRisk && !overCreditLimit && !possibleDuplicate && !remindersIgnored && !discountIsLarge() && (limit == null || total.compareTo(limit) <= 0)) {
        return Approval.NOT_NEEDED;
    }
    return approvalsAt(total, today) < approvalsRequired(taxRate) ? Approval.NEEDS_APPROVAL : Approval.APPROVED;
}

/**
 * The approvals a draft needs: two when its client is a HIGH payment risk or its grand total is more than
 * one and a half times the approval limit, else one.
 */
public int approvalsRequired(BigDecimal taxRate) {
    if (highRiskClient) {
        return 2;
    }
    BigDecimal limit = approvalLimit();
    return limit != null && approvalTotal(taxRate).compareTo(limit.multiply(new BigDecimal("1.5"))) > 0 ? 2 : 1;
}

/**
 * The approvals that still stand for the grand total as of today: those given at that total or a higher one,
 * unless more than {@link #approvalDays} days have passed since the last of them; else none.
 */
private int approvalsAt(BigDecimal total, LocalDate today) {
    if (approvedTotal == null || total.compareTo(approvedTotal) > 0) {
        return 0;
    }
    boolean lapsed = approvedOn != null && today.isAfter(afterDays(approvedOn, approvalDays()));
    return lapsed ? 0 : approvals;
}

/** The approvals the invoice still needs before it is sent, given its approval: none unless it needs approval. */
public int approvalsNeeded(Approval approval, BigDecimal taxRate, LocalDate today) {
    if (approval != Approval.NEEDS_APPROVAL) {
        return 0;
    }
    return Math.max(1, approvalsRequired(taxRate) - approvalsAt(approvalTotal(taxRate), today));
}

/** The approvals that stand for the grand total as of today (see {@link #approvalsNeeded}). */
public int approvalsGiven(BigDecimal taxRate, LocalDate today) {
    return approvalsAt(approvalTotal(taxRate), today);
}

public int getApprovals() {
    return approvals;
}

public BigDecimal getApprovedTotal() {
    return approvedTotal;
}

public LocalDate getApprovedOn() {
    return approvedOn;
}

/**
 * Approves the invoice at the grand total on the day: one more approval when the approvals given still
 * stand for that total, else its first.
 */
public void approve(BigDecimal total, LocalDate on) {
    this.approvals = approvalsAt(total, on) + 1;
    this.approvedTotal = total;
    this.approvedOn = on;
}

